import math
import random

def color_graph(adj: list[list[int]]) -> list[int]:
    # Handle trivial cases
    if not adj:
        return []
    n = len(adj)
    if n == 0:
        return []
    if n == 1:
        return [0]

    # Detect input format: adjacency matrix (square binary) vs adjacency list
    is_matrix = False
    if n > 0 and isinstance(adj[0], list) and len(adj[0]) == n:
        is_matrix = True
        for i in range(n):
            if not isinstance(adj[i], list) or len(adj[i]) != n:
                is_matrix = False
                break
            for val in adj[i]:
                if val not in (0, 1):
                    is_matrix = False
                    break
            if not is_matrix:
                break

    # Build neighbor sets for O(1) adjacency checks and efficient iteration
    if is_matrix:
        neighbors = [set(j for j in range(n) if adj[i][j] == 1) for i in range(n)]
    else:
        neighbors = [set(lst) for lst in adj]

    # Handle edgeless graph
    if all(len(neighbors[i]) == 0 for i in range(n)):
        return [0] * n

    # Precompute degrees for use in heuristics
    degrees = [len(neighbors[i]) for i in range(n)]

    # Helper: greedy coloring with given vertex order
    def greedy_color(order):
        color = [-1] * n
        for v in order:
            used = [False] * (n + 1)  # +1 for safety
            for u in neighbors[v]:
                if color[u] != -1:
                    used[color[u]] = True
            c = 0
            while used[c]:
                c += 1
            color[v] = c
        return color

    # Helper: compute number of colors used in a coloring
    def num_colors(coloring):
        if not coloring:
            return 0
        return max(coloring) + 1

    # Helper: validate coloring (lightweight, for safety)
    def is_valid(coloring):
        for v in range(n):
            cv = coloring[v]
            for u in neighbors[v]:
                if coloring[u] == cv:
                    return False
        return True

    # === HEURISTIC 1: DSATUR with Optimized Updates ===
    def dsatur():
        color = [-1] * n
        saturation = [0] * n
        neighbor_colors = [set() for _ in range(n)]
        uncolored = set(range(n))

        if not uncolored:
            return color

        # Start with vertex of highest degree
        v = max(uncolored, key=lambda x: degrees[x])
        color[v] = 0
        uncolored.remove(v)
        for u in neighbors[v]:
            if u in uncolored:
                if 0 not in neighbor_colors[u]:
                    neighbor_colors[u].add(0)
                    saturation[u] += 1

        while uncolored:
            max_sat = -1
            candidates = []
            for v in uncolored:
                if saturation[v] > max_sat:
                    max_sat = saturation[v]
                    candidates = [v]
                elif saturation[v] == max_sat:
                    candidates.append(v)

            if len(candidates) > 1:
                # Tie-breaking: max degree in the uncolored subgraph
                max_deg = -1
                deg_candidates = []
                for v in candidates:
                    deg = 0
                    for u in neighbors[v]:
                        if u in uncolored:
                            deg += 1
                    if deg > max_deg:
                        max_deg = deg
                        deg_candidates = [v]
                    elif deg == max_deg:
                        deg_candidates.append(v)
                if len(deg_candidates) > 1:
                    v = random.choice(deg_candidates)
                else:
                    v = deg_candidates[0]
            else:
                v = candidates[0]

            # Find smallest available color (MEX)
            used = neighbor_colors[v]
            c = 0
            while c in used:
                c += 1
            color[v] = c

            # Remove v from uncolored and update neighbors
            uncolored.remove(v)
            for u in neighbors[v]:
                if u in uncolored:
                    if c not in neighbor_colors[u]:
                        neighbor_colors[u].add(c)
                        saturation[u] += 1
        return color

    # === HEURISTIC 2: Recursive Largest First (RLF) Optimized ===
    def rlf():
        color = [-1] * n
        uncolored = set(range(n))
        current_color = 0

        while uncolored:
            # Vertex with max degree in uncolored subgraph
            v = max(uncolored, key=lambda x: sum(1 for u in neighbors[x] if u in uncolored))
            independent_set = {v}

            # U: eligible (not adjacent to independent_set), W: ineligible
            U = uncolored - {v}
            W = set(u for u in neighbors[v] if u in uncolored)
            U -= W

            while U:
                # u in U with max |N(u) ∩ W|
                max_nw = -1
                candidates = []
                for u in U:
                    nw = sum(1 for w in neighbors[u] if w in W)
                    if nw > max_nw:
                        max_nw = nw
                        candidates = [u]
                    elif nw == max_nw:
                        candidates.append(u)

                if len(candidates) > 1:
                    # Tie-break: min degree in G[U]
                    min_deg = float('inf')
                    deg_candidates = []
                    for u in candidates:
                        deg = sum(1 for w in neighbors[u] if w in U)
                        if deg < min_deg:
                            min_deg = deg
                            deg_candidates = [u]
                        elif deg == min_deg:
                            deg_candidates.append(u)
                    if len(deg_candidates) > 1:
                        u = random.choice(deg_candidates)
                    else:
                        u = deg_candidates[0]
                else:
                    u = candidates[0]

                independent_set.add(u)
                U.remove(u)
                # Move neighbors of u from U to W
                for w in neighbors[u]:
                    if w in U:
                        U.remove(w)
                        W.add(w)

                for node in independent_set:
                    color[node] = current_color

                uncolored -= independent_set
                current_color += 1

        return color

    # === HEURISTIC 3: Smallest-Last (Degeneracy Ordering) ===
    def smallest_last():
        if n == 0:
            return []
        deg = degrees[:]  # Work on a copy
        order = []
        remaining = set(range(n))
        max_deg = max(deg) if n > 0 else 0
        # Bucket sort: buckets[d] = list of vertices with degree d
        buckets = [[] for _ in range(max_deg + 1)]
        for v in range(n):
            d = deg[v]
            if d <= max_deg:
                buckets[d].append(v)

        ptr = 0
        for _ in range(n):
            # Find the first non-empty bucket
            while ptr <= max_deg and not buckets[ptr]:
                ptr += 1
            if ptr > max_deg:
                break  # Should not happen for valid graph
            v = buckets[ptr].pop()
            order.append(v)
            remaining.remove(v)
            # Update degrees of neighbors
            for u in neighbors[v]:
                if u in remaining:
                    deg[u] -= 1
                    d_new = deg[u]
                    if d_new <= max_deg:
                        buckets[d_new].append(u)
        # Color in reverse peeling order
        return greedy_color(order[::-1])

    # === HEURISTIC 4: Welsh-Powell (Largest-First) ===
    def welsh_powell():
        order = sorted(range(n), key=lambda x: degrees[x], reverse=True)
        return greedy_color(order)

    # Generate initial colorings from multiple heuristics
    heuristics = [dsatur, rlf, smallest_last, welsh_powell]
    best_coloring = None
    best_num_colors = float('inf')

    for heuristic in heuristics:
        try:
            coloring = heuristic()
            if not is_valid(coloring):
                continue
            num = num_colors(coloring)
            if num < best_num_colors:
                best_num_colors = num
                best_coloring = coloring[:]
        except Exception:
            # Fallback: greedy on degree order
            coloring = greedy_color(sorted(range(n), key=lambda x: degrees[x], reverse=True))
            if is_valid(coloring):
                num = num_colors(coloring)
                if num < best_num_colors:
                    best_num_colors = num
                    best_coloring = coloring[:]

    # If no heuristic worked (should not happen), use trivial coloring
    if best_coloring is None:
        best_coloring = list(range(n))  # worst case: each vertex unique color
        # But we can do better: greedy on random order
        order = list(range(n))
        random.shuffle(order)
        best_coloring = greedy_color(order)

    # === LOCAL SEARCH: Kempe Chain-Based Color Reduction with Iteration Limit ===
    def kempe_reduce(coloring):
        if n <= 1:
            return coloring

        color = coloring[:]
        improved = True
        passes = 0
        max_passes = 10  # Limit passes to ensure termination within time budget

        while improved and passes < max_passes:
            improved = False
            passes += 1
            k = num_colors(color)
            # Try to eliminate color classes from highest to lowest (skip 0)
            for target_color in range(k-1, 0, -1):
                # Get all vertices currently colored with target_color
                target_vertices = [v for v in range(n) if color[v] == target_color]
                if not target_vertices:
                    continue  # This color class is already empty

                # Try to recolor each vertex in the target class
                for v in target_vertices:
                    # Build set of colors used by neighbors of v
                    neighbor_colors = set()
                    for u in neighbors[v]:
                        neighbor_colors.add(color[u])

                    # Try direct reassignment to a lower color
                    for c in range(target_color):
                        if c not in neighbor_colors:
                            color[v] = c
                            improved = True
                            break
                    if improved:
                        break  # Break to restart scan from highest color

                    # Try Kempe chains for each lower color c
                    for c in range(target_color):
                        # Build the (c, target_color) Kempe chain component containing v
                        stack = [v]
                        visited = set([v])
                        component = []
                        while stack:
                            node = stack.pop()
                            component.append(node)
                            for u in neighbors[node]:
                                if u not in visited and (color[u] == c or color[u] == target_color):
                                    visited.add(u)
                                    stack.append(u)

                        comp_set = set(component)
                        # Condition for Kempe swap (c, target_color) to allow v to take color c:
                        #   (a) Every neighbor of v with color c must be in the component (so they change away from c)
                        #   (b) No neighbor of v with color target_color is in the component (so they don't become c and conflict with v)
                        condition_a = True
                        condition_b = True
                        for u in neighbors[v]:
                            if color[u] == c:
                                if u not in comp_set:
                                    condition_a = False
                                    break
                            elif color[u] == target_color:
                                if u in comp_set:
                                    condition_b = False
                                    break

                        if condition_a and condition_b:
                            # Perform the swap: c <-> target_color in the component
                            for node in component:
                                if color[node] == c:
                                    color[node] = target_color
                                else:  # must be target_color
                                    color[node] = c
                            improved = True
                            break  # Break Kempe chain loop
                    if improved:
                        break  # Break vertex loop
                if improved:
                    break  # Break target_color loop to restart from highest

        return color

    # Apply Kempe reduction to the best initial coloring
    best_coloring = kempe_reduce(best_coloring)

    return best_coloring

