def _dsatur(neighbors, n, random_tiebreak=False):
    if n == 0:
        return []
    colors = [-1] * n
    saturated = [set() for _ in range(n)]
    uncolored = set(range(n))
    for _ in range(n):
        if not uncolored:
            break
        max_sat = -1
        candidates = []
        for v in uncolored:
            sat = len(saturated[v])
            if sat > max_sat:
                max_sat = sat
                candidates = [v]
            elif sat == max_sat:
                candidates.append(v)
        if not candidates:
            break  # Should not happen
        if len(candidates) == 1:
            v = candidates[0]
        else:
            # Tie-break by degree in uncolored subgraph
            max_deg = -1
            deg_candidates = []
            for v in candidates:
                deg = len([u for u in neighbors[v] if u in uncolored])
                if deg > max_deg:
                    max_deg = deg
                    deg_candidates = [v]
                elif deg == max_deg:
                    deg_candidates.append(v)
            if not deg_candidates:
                v = random.choice(candidates)
            elif len(deg_candidates) == 1:
                v = deg_candidates[0]
            else:
                if random_tiebreak:
                    v = random.choice(deg_candidates)
                else:
                    v = deg_candidates[0]  # deterministic: smallest index
        # Assign smallest available color
        used = saturated[v]
        c = 0
        while c in used:
            c += 1
        colors[v] = c
        uncolored.remove(v)
        # Update saturation of uncolored neighbors
        for u in neighbors[v]:
            if u in uncolored:
                saturated[u].add(c)
    return colors

def _rlf_variant(neighbors, n, variant=0):
