def _smallest_last_variant(neighbors, n, variant=0):
    if n == 0:
        return []
    # Compute smallest-last ordering
    remaining = set(range(n))
    order = []
    # We'll use simple approach since n <= 100
    while remaining:
        if variant == 0:
            # Standard: min degree in remaining subgraph
            min_deg = math.inf
            v_min = -1
            for v in remaining:
                deg = len([u for u in neighbors[v] if u in remaining])
                if deg < min_deg:
                    min_deg = deg
                    v_min = v
        elif variant == 1:
            # Min degree, tie-break by max degree in original graph (to break symmetry)
            min_deg = math.inf
            candidates = []
            for v in remaining:
                deg = len([u for u in neighbors[v] if u in remaining])
                if deg < min_deg:
