    for v in reversed(order):
        used = set()
        for u in neighbors[v]:
            if colors[u] != -1:
                used.add(colors[u])
        c = 0
        while c in used:
            c += 1
        colors[v] = c
    return colors

def _greedy_with_ordering(neighbors, n, ordering):
    colors = [-1] * n
    for v in ordering:
        used = set()
        for u in neighbors[v]:
            if colors[u] != -1:
                used.add(colors[u])
        c = 0
        while c in used:
            c += 1
        colors[v] = c
    return colors

def _clique_lower_bound(neighbors, n):
    # Simple lower bound: size of maximum clique via greedy heuristic
    # Since n <= 100, we can use a simple greedy clique finding
    if n == 0:
        return 0
    remaining = set(range(n))
    clique_size = 0
    while remaining:
        # Pick vertex of max degree in remaining subgraph
        max_deg = -1
        v_max = -1
        for v in remaining:
            deg = len([u for u in neighbors[v] if u in remaining])
            if deg > max_deg:
                max_deg = deg
                v_max = v
        # Form clique with v_max and its neighbors that are all mutually adjacent
        clique = {v_max}
        neighbors_in_remaining = {u for u in neighbors[v_max] if u in remaining}
        # Greedily add vertices that are adjacent to all current clique members
        for u in list(neighbors_in_remaining):
            if all(w in neighbors[u] for w in clique):
                clique.add(u)
        clique_size = max(clique_size, len(clique))
        # Remove clique vertices from remaining
        remaining -= clique
    return clique_size

def _kempe_improve(colors, neighbors, n, k):
