                            if colors[x] == target_color:
                                colors[x] = c
                            elif colors[x] == c:
                                colors[x] = target_color
                        improved = True
                        # v is now color c, break out of c loop for this v
                        break
                # If we changed color of v, break to restart the verts list for this target_color
                if colors[v] != target_color:
                    break
            # After processing all verts for this target_color, if none remain, we can break early for this pass
            if not any(v for v in range(n) if colors[v] == target_color):
